  let _ultimaPantallaEvento = '';
  function goTo(screenId, opciones) {
    if (screenId !== _ultimaPantallaEvento) { _ultimaPantallaEvento = screenId; kEvento('pantalla', { pantalla: screenId }); }
    if (screenId !== 'legal' && /^#(aviso-legal|privacidad|terminos|cookies)$/.test(location.hash)) {
      try { history.replaceState(history.state, '', location.pathname + location.search); } catch (e) {}
    }
    document.documentElement.classList.remove('con-sesion', 'portada-esperando');
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
    document.getElementById(screenId).classList.add('active');
    if (!(opciones && opciones.mantenerScroll)) window.scrollTo(0,0);
    if (screenId === 'registro' || screenId === 'login') { try { _pintarPlanPendiente(); } catch (e) {} }
    const btnVolver = document.getElementById('btnVolverDashboard');
    if (btnVolver) {
      const user = getCurrentUser();
      btnVolver.style.display = (screenId === 'landing' && user && getUserData(user.email)?.plan) ? '' : 'none';
    }
    const gymBg = document.querySelector('.gym-bg-deco');
    if (gymBg) gymBg.style.display = screenId === 'landing' ? '' : 'none';
  }

