  // ===== LEAD MAGNET (landing) =====
  async function submitLeadEmail(event) {
    event.preventDefault();
    const input = document.getElementById('leadEmail');
    const email = input.value.trim();
    if (!email) return false;

    // Rate limiting: máx 1 envío por dispositivo cada 60 segundos
    const RL_KEY = 'kone_lead_ts';
    const ahora = Date.now();
    try {
      const ultimo = parseInt(localStorage.getItem(RL_KEY) || '0', 10);
      if (ahora - ultimo < 60000) {
        document.getElementById('leadMagnetNote').textContent = 'Ya hemos apuntado tu email. ¡Nos vemos pronto!';
        input.value = '';
        return false;
      }
      localStorage.setItem(RL_KEY, String(ahora));
    } catch (e) { /* localStorage bloqueado: dejamos pasar */ }

    input.value = '';
    document.getElementById('leadMagnetNote').textContent = 'Hecho. En cuanto decidas dar el paso, aquí tienes tu plan esperando.';
    supa.from('leads').insert({ email }).then(({ error }) => {
      if (error && error.code !== '23505') console.error('Error guardando lead:', error);
      if (!error) notificarAdmin('lead', { email });
    });
    return false;
  }

