  // Devuelve [id, título] del vídeo de técnica, o null si no hay uno elegido.
  function videoTecnica(nombreEjercicio) {
    const n = (nombreEjercicio || '').toLowerCase()
      .normalize('NFD').replace(/[̀-ͯ]/g, '')
      .replace(/\([^)]*\)/g, ' ').replace(/\s+/g, ' ').trim();
    let mejor = null, mejorPos = Infinity;
    for (const [re, id, t] of VIDEO_TECNICA) {
      const m = re.exec(n);
      if (m && m.index < mejorPos) { mejor = [id, t]; mejorPos = m.index; }
    }
    return mejor;
  }

  function getVideoUrl(nombreEjercicio) {
    const v = videoTecnica(nombreEjercicio);
    if (v) return `https://www.youtube.com/watch?v=${v[0]}`;
    // Ejercicio sin vídeo elegido (uno que el cliente añade a mano, por
    // ejemplo): búsqueda en español como hasta ahora.
    return `https://www.youtube.com/results?search_query=${encodeURIComponent(nombreEjercicio + ' técnica correcta')}`;
  }

  // ===== FICHA DE EJERCICIO =====
  // Instrucciones paso a paso en español + músculos trabajados. Datos del dataset
  // MIT hasaneyldrm/exercises-dataset (solo datos; sin medios de GymVisual).
  // Se cargan bajo demanda la primera vez que se abre una ficha (46 KB).
  let _infoEjercicios = null, _infoEjerciciosKeys = null;
  async function _cargarInfoEjercicios() {
    if (_infoEjercicios) return;
    try {
      const r = await fetch('/data/ejercicios-info.json?v=20261027a');
      _infoEjercicios = r.ok ? await r.json() : {};
    } catch (e) { _infoEjercicios = {}; }
    // claves más largas primero para que "curl martillo" gane a "curl"
    _infoEjerciciosKeys = Object.keys(_infoEjercicios).sort((a, b) => b.length - a.length);
  }
  // Palabras de equipo/variante que cambian el ejercicio de verdad (no es lo
  // mismo "remo" que "remo en máquina" o "remo mancuerna a un brazo", ni
  // "sentadilla" que "sentadilla búlgara"). El emparejamiento de abajo busca
  // la clave MÁS LARGA que sea substring del nombre real, pero con ~200
  // fichas no hay una para cada variante -- así que a veces "gana" una clave
  // corta y genérica ("remo") para un nombre mucho más específico. Antes eso
  // se traducía en enseñar fotos/pasos de OTRO ejercicio con normalidad (bug
  // real reportado por el usuario ago 2026: "remo mancuerna a un brazo"
  // mostraba la ficha de remo con barra). Sin acentos, igual que
  // normalizarEjercicio() y las claves del JSON.
  const _EQUIPO_VARIANTE = ['mancuerna', 'mancuernas', 'barra', 'polea', 'maquina', 'kettlebell',
    'banda', 'disco', 'goblet', 'sumo', 'rumano', 'bulgara', 'declinado', 'inclinado', 'cerrado',
    'martillo', 'concentrado', 'predicador', 'apoyado', 'alterno', 'pendlay', 'gironda', 'menton', 'militar',
    // 16 sept 2026: "Remo australiano bajo mesa" abría la ficha del remo con
    // barra, y "Press inclinado en multipower" la de mancuernas.
    'australiano', 'invertido', 'multipower'];
  // Qué ficha (fotos e instrucciones) corresponde a un ejercicio. La usan «Cómo se
  // hace» y la foto del modo entrenamiento, para que las dos enseñen lo mismo.
  function _claveFichaEjercicio(nombre) {
    const n = normalizarEjercicio(nombre);
    let key = (_infoEjerciciosKeys || []).find(k => n.includes(k));
    if (key && key.split(' ').length <= 2) {
      const noCubre = _EQUIPO_VARIANTE.some(w => n.includes(w) && !key.includes(w));
      if (noCubre) key = null;
    }
    if (key && /una pierna/.test(n) && /^peso muerto/.test(key) && !key.includes('pierna')) key = null;
    if (key && !key.includes(' ')) {
      const partesLista = n.split(/\s+(?:y|o)\s+/);
      if (partesLista.length > 1 && !partesLista[0].includes(key)) key = null;
    }
    return key;
  }

  async function abrirInfoEjercicio(nombre, diaNombre) {
    await _cargarInfoEjercicios();
    const n = normalizarEjercicio(nombre);
    let key = (_infoEjerciciosKeys || []).find(k => n.includes(k));
    // Si la clave encontrada es corta/genérica (1-2 palabras) y el nombre real
    // menciona un equipo o variante que esa clave NO cubre, no es una ficha
    // fiable para este ejercicio -- mejor mandar al vídeo (siempre correcto)
    // que dar por buena una foto de un movimiento distinto.
    if (key && key.split(' ').length <= 2) {
      const noCubre = _EQUIPO_VARIANTE.some(w => n.includes(w) && !key.includes(w));
      if (noCubre) key = null;
    }
    // Unilateral frente a bilateral: la ficha de "peso muerto (rumano)" enseña
    // el movimiento a dos piernas, que no se parece al de una pierna.
    if (key && /una pierna/.test(n) && /^peso muerto/.test(key) && !key.includes('pierna')) key = null;
    // Listas "X y Y" / "X o Y": una clave de UNA palabra que solo aparece
    // detrás del "y"/"o" no es el ejercicio principal ("Bici y remo" abría el
    // remo con peso).
    if (key && !key.includes(' ')) {
      const partesLista = n.split(/\s+(?:y|o)\s+/);
      if (partesLista.length > 1 && !partesLista[0].includes(key)) key = null;
    }
    const info = key ? _infoEjercicios[key] : null;
    if (!info) {
      // Sin ficha para este ejercicio: llevamos directamente al vídeo de técnica
      window.open(getVideoUrl(nombre), '_blank', 'noopener');
      return;
    }
    _renderSustitucionEjercicioUI(nombre, diaNombre);
    document.getElementById('infoEjercicioTitulo').textContent = nombre;
    // Fotos del movimiento (inicio / final). Dominio público (free-exercise-db).
    const fotos = document.getElementById('infoEjercicioFotos');
    const etiquetas = ['Posición inicial', 'Posición final'];
    fotos.innerHTML = (info.img || []).map((src, i) =>
      `<figure class="ej-foto"><img src="${src}" alt="${nombre} — ${etiquetas[i] || ''}" loading="lazy">
       <figcaption>${etiquetas[i] || ''}</figcaption></figure>`).join('');
    fotos.style.display = (info.img && info.img.length) ? 'grid' : 'none';
    const musEl = document.getElementById('infoEjercicioMusculos');
    musEl.innerHTML = (info.m ? `<span class="musculo-chip principal">${info.m}</span>` : '') +
      (info.s || []).map(s => `<span class="musculo-chip">${s}</span>`).join('');
    musEl.previousElementSibling.style.display = info.m ? '' : 'none';
    musEl.style.display = info.m ? 'flex' : 'none';
    const pasosEl = document.getElementById('infoEjercicioPasos');
    pasosEl.innerHTML = (info.pasos || []).map((p, i) =>
      `<div class="paso-ejercicio"><span class="paso-ejercicio-num">${String(i + 1).padStart(2, '0')}</span><span>${_esc(p)}</span></div>`).join('');
    pasosEl.previousElementSibling.style.display = (info.pasos && info.pasos.length) ? '' : 'none';
    pasosEl.style.display = (info.pasos && info.pasos.length) ? 'flex' : 'none';
    const consejosEl = document.getElementById('infoEjercicioConsejos');
    if (info.consejos && info.consejos.length) {
      consejosEl.innerHTML = `
        <div style="font-size:11px;color: var(--brasa-txt);font-family:'DM Mono',monospace;font-weight:500;letter-spacing:1.5px;margin-bottom:10px">CONSEJOS</div>
        <ul class="ejercicio-consejos-list">${info.consejos.map(c => `<li>${_esc(c)}</li>`).join('')}</ul>`;
      consejosEl.style.display = '';
    } else {
      consejosEl.innerHTML = '';
      consejosEl.style.display = 'none';
    }
    document.getElementById('infoEjercicioVideo').href = getVideoUrl(nombre);
    document.getElementById('modalInfoEjercicio').classList.add('visible');
  }

