  // Solo nutrición: se quitan las frases de gimnasio (13 de 60: "Entrena como si
  // nadie te viera"...) porque el cliente no entrena con nosotros (30 sept 2026).
  function getMensajeDia(soloNutri) {
    const inicio = new Date(new Date().getFullYear(), 0, 0);
    const dayOfYear = Math.floor((Date.now() - inicio) / 86400000);
    const racha = calcularRachaDias ? calcularRachaDias() : 0;
    // Cada 3 días, los usuarios con racha alta ven un mensaje personalizado con su número
    if (racha >= 14 && dayOfYear % 3 === 0) {
      const streakMsgs = [
        `${racha} días seguidos. Eso ya es un hábito. Sigue.`,
        `${racha} días sin parar. La mayoría ya lo habría dejado.`,
        `${racha} días de racha. No es motivación. Es identidad.`
      ];
      return streakMsgs[dayOfYear % streakMsgs.length];
    }
    const _RE_ENTRENO = /entren|gimnasio|repetici|series|sudor|\bbarra\b/i;
    const lista = soloNutri
      ? MENSAJES_DIA.filter(x => !_RE_ENTRENO.test(x) || /plato|alimentaci/i.test(x))
      : MENSAJES_DIA;
    return lista[dayOfYear % lista.length];
  }

