      const _sinIntervalos = enfermedad.includes('Hipertensión') || enfermedad.includes('cardíacos');
      const _conZona2 = mejorarResistencia || sentirseMejor || (perdidaGrasa && _sinIntervalos);
      const finisher3 = (perdidaGrasa && !_sinIntervalos) ? _finisherInterval : (_conZona2 ? _cardioZona2 : '');
      const finisher4 = finisher3;
      const sVol = ganarMusculo ? '4' : '3';
      const volP = ganarMusculo ? '5' : '4';
      const volA = ganarMusculo ? '4' : '3';

        // ── GIMNASIO / EN CASA CON MATERIAL → pesos libres + máquinas ──
        // ≤2 días (cualquier nivel) o principiante con 3 días → Full Body, máxima frecuencia
        // FULL BODY A/B CON BARRA para quien ya lleva tiempo (14 sept 2026).
        //
        // Antes esta rama servía la MISMA plantilla a los tres niveles: alguien
