  async function enviarEncuesta() {
    const texto = (document.getElementById('encuestaTexto')?.value || '').trim();
    const autorizar = document.getElementById('encuestaAutorizar')?.checked ?? true;
    document.getElementById('modalEncuesta').classList.remove('visible');

    const user = getCurrentUser();
    userData.testimonioCompletado = true;
    if (_encuestaEstrellas > 0 || texto) {
      userData.testimonio = {
        estrellas: _encuestaEstrellas,
        texto,
        autorizado: autorizar,
        fecha: new Date().toISOString()
      };
    }
    if (user) {
      saveUserData(user.email, { userData, plan: generatedPlan, savedAt: new Date().toISOString() });
    }

    if (autorizar && _encuestaEstrellas > 0 && user) {
      const edad = userData.edad ? parseInt(userData.edad) : null;
      const deporte = userData.deporte || '';
      const tipoPlan = userData.tipoPlan || '';
      const planTexto = tipoPlan.includes('Solo') ? 'Solo nutrición' : (deporte || 'Plan K-One');
      const inicial = user.nombre ? user.nombre.split(' ').map(p => p[0]).join('').slice(0, 2).toUpperCase() : '?';
      const nombrePublico = user.nombre ? (() => {
        const parts = user.nombre.trim().split(' ');
        return parts.length > 1 ? `${parts[0]} ${parts[1][0]}.` : parts[0];
      })() : 'Cliente';
      await supa.from('testimonios').insert({
        nombre: nombrePublico,
        inicial,
        edad,
        plan: planTexto,
        estrellas: _encuestaEstrellas,
        texto: texto || null
      });
      notificarAdmin('opinion', { nombre: nombrePublico, estrellas: _encuestaEstrellas, texto: texto || '(sin texto)' });
    }

    if (_onEncuestaCerrada) _onEncuestaCerrada();
    _onEncuestaCerrada = null;
  }

  function cerrarEncuesta() {
    document.getElementById('modalEncuesta').classList.remove('visible');
    userData.testimonioCompletado = true;
    const user = getCurrentUser();
    if (user) saveUserData(user.email, { userData, plan: generatedPlan, savedAt: new Date().toISOString() });
    if (_onEncuestaCerrada) _onEncuestaCerrada();
    _onEncuestaCerrada = null;
  }

  // ===== NOTIFICACIÓN AL ADMIN POR EMAIL =====
  async function notificarAdmin(tipo, datos) {
    // /api/notify exige sesión solo para 'opinion' (tiposProtegidos);
    // 'bienvenida' se envía justo tras signUp(), cuando todavía no hay sesión
    // (el proyecto exige confirmar email), así que va sin token -- protegido en
    // el servidor con rate-limit por IP en vez de auth. Para los tipos que sí
    // exigen sesión, si no hay token la petición devuelve 401 en silencio
    // (fetch().catch(()=>{}) no distingue status HTTP de fallo de red).
    const headers = { 'Content-Type': 'application/json' };
    try {
      const { data: { session } } = await supa.auth.getSession();
      if (session?.access_token) headers['Authorization'] = `Bearer ${session.access_token}`;
    } catch (e) {}
    // ANTES: fetch(...).catch(()=>{}) — dispara y olvida. Si la petición no
    // salía (red caída, bloqueador de anuncios, la pestaña se cierra antes de
    // que salga, un 429 del rate-limit o un 5xx puntual), el aviso se perdía
    // EN SILENCIO y nadie se enteraba: ni el admin recibía el "nuevo registro"
    // ni quedaba rastro. Pasó de verdad con un alta del 6 sept 2026.
    // Ahora el resultado se comprueba y, si falla, el aviso queda pendiente en
    // localStorage y se reintenta en el siguiente arranque de la app.
    try {
      const r = await fetch('/api/notify', {
        method: 'POST', headers, body: JSON.stringify({ tipo, datos })
      });
      if (r.ok) return true;
      console.warn('[notify] respuesta no OK:', r.status);
    } catch (e) {
      console.warn('[notify] no se pudo enviar:', e.message);
    }
    _guardarNotificacionPendiente(tipo, datos);
    return false;
  }

  // Cola de avisos que no llegaron a enviarse. Solo se guardan los tipos que
  // no exigen sesión, porque son los que se disparan en momentos frágiles
  // (registro, lead) y los únicos que se pueden reintentar sin token.
  const _TIPOS_REINTENTABLES = ['bienvenida', 'lead'];
  function _guardarNotificacionPendiente(tipo, datos) {
    if (!_TIPOS_REINTENTABLES.includes(tipo)) return;
    try {
      const cola = JSON.parse(localStorage.getItem('kone_notif_pendientes') || '[]');
      // Sin duplicados del mismo tipo+email, y tope de 5 para no crecer sin fin.
      const clave = tipo + '|' + (datos.email || '');
      if (cola.some(x => x.clave === clave)) return;
      cola.push({ clave, tipo, datos, ts: Date.now() });
      localStorage.setItem('kone_notif_pendientes', JSON.stringify(cola.slice(-5)));
    } catch (e) {}
  }

  async function _reintentarNotificacionesPendientes() {
    let cola;
    try { cola = JSON.parse(localStorage.getItem('kone_notif_pendientes') || '[]'); } catch (e) { return; }
    if (!cola.length) return;
    // Se descartan los avisos de más de 7 días: a esas alturas ya no aportan.
    const vivos = cola.filter(x => Date.now() - (x.ts || 0) < 7 * 24 * 60 * 60 * 1000);
    const fallidos = [];
    for (const item of vivos) {
      const headers = { 'Content-Type': 'application/json' };
      try {
        const r = await fetch('/api/notify', {
          method: 'POST', headers, body: JSON.stringify({ tipo: item.tipo, datos: item.datos })
        });
        if (!r.ok) fallidos.push(item);
      } catch (e) { fallidos.push(item); }
    }
    try {
      if (fallidos.length) localStorage.setItem('kone_notif_pendientes', JSON.stringify(fallidos));
      else localStorage.removeItem('kone_notif_pendientes');
    } catch (e) {}
  }

