  // ===== TESTIMONIALES: CARGA DINÁMICA DESDE SUPABASE =====
  function _mostrarTestimoniosVacios() {
    const carousel = document.getElementById('testimonialsCarousel');
    const empty = document.getElementById('testimonialsEmpty');
    if (carousel) carousel.style.display = 'none';
    if (empty) empty.style.display = '';
  }

  async function cargarTestimoniosLanding() {
    const track = document.getElementById('testimonialsTrack');
    if (!track) return;
    try {
      const { data, error } = await supa
        .from('testimonios')
        .select('nombre, inicial, edad, plan, estrellas, texto')
        .order('created_at', { ascending: false })
        .limit(20);
      if (error) throw error;
      // Antes, si no había opiniones reales todavía se rellenaba con 5
      // testimonios inventados (mismo diseño de tarjeta, sin ningún
      // distintivo) — contradecía el propio texto de la sección ("sin
      // inventar") y es justo el tipo de reseña falsa que la Directiva UE
      // 2019/2161 prohíbe expresamente. Ahora, sin datos reales, se usa
      // siempre el estado vacío honesto que ya existía en el código.
      if (!data || !data.length) {
        _mostrarTestimoniosVacios();
        _actualizarReviewSchema(null);
        return;
      }
      _actualizarReviewSchema(data);
      // Nota media junto a los distintivos de confianza, con el mismo formato que ellos.
      // Solo la nota: NO se enseña cuántas opiniones hay (decisión del 1 oct 2026). Se
      // calcula con las opiniones publicadas y solo se muestra con 5 o más, para que la
      // media diga algo.
      try {
        const chipNota = document.getElementById('heroRating');
        if (chipNota && data.length >= 5) {
          const media = data.reduce((acc, r) => acc + Math.max(1, Math.min(5, r.estrellas || 5)), 0) / data.length;
          [...chipNota.childNodes].filter(n => n.nodeType === 3).forEach(n => n.remove());
          chipNota.appendChild(document.createTextNode('Valoración ' + media.toFixed(1).replace('.', ',')));
          chipNota.style.display = '';
        }
      } catch (e) {}
      const carousel = document.getElementById('testimonialsCarousel');
      const empty = document.getElementById('testimonialsEmpty');
      if (carousel) carousel.style.display = '';
      if (empty) empty.style.display = 'none';
      track.innerHTML = data.map(t => {
        const estrellas = '★'.repeat(Math.max(1, Math.min(5, t.estrellas || 5))) +
                          '☆'.repeat(5 - Math.max(1, Math.min(5, t.estrellas || 5)));
        // t.nombre/t.inicial pueden venir de cualquiera (el formulario público
        // de opinión no exige login) -- antes se volcaban sin escapar, XSS
        // almacenado explotable contra cualquier visitante de la landing.
        const quoteHTML = t.texto ? `<p class="testimonial-quote">"${_esc(t.texto)}"</p>` : '';
        const planSafe = t.plan ? _esc(t.plan) : '';
        const roleText = [t.edad ? `${parseInt(t.edad) || t.edad} años` : '', planSafe ? `<b>${planSafe}</b>` : ''].filter(Boolean).join(' · ');
        const nombreSafe = _esc(t.nombre || 'Cliente');
        const inicialSafe = _esc((t.inicial || t.nombre?.[0] || '?').toUpperCase());
        return `<div class="testimonial-card">
          <div class="testimonial-stars">${estrellas}</div>
          ${quoteHTML}
          <div class="testimonial-author">
            <div class="testimonial-avatar">${inicialSafe}</div>
            <div>
              <div class="testimonial-name">${nombreSafe}</div>
              <div class="testimonial-role">${roleText}</div>
            </div>
          </div>
        </div>`;
      }).join('');
    } catch (e) {
      _mostrarTestimoniosVacios();
      _actualizarReviewSchema(null);
    }
  }

  // Genera/actualiza (o retira) el JSON-LD de Review + AggregateRating del
  // Product ya declarado en el @graph del <head> (mismo @id: se fusionan).
  // Recibe SIEMPRE opiniones reales de Supabase o null — nunca el fallback.
  function _actualizarReviewSchema(reviews) {
    let el = document.getElementById('reviewSchemaLd');
    if (!reviews || !reviews.length) {
      if (el) el.remove();
      return;
    }
    const nota = r => Math.max(1, Math.min(5, r.estrellas || 5));
    const suma = reviews.reduce((s, r) => s + nota(r), 0);
    const schema = {
      "@context": "https://schema.org",
      "@type": "Product",
      "@id": "https://k-one.fit/#product",
      "aggregateRating": {
        "@type": "AggregateRating",
        "ratingValue": (suma / reviews.length).toFixed(1),
        "reviewCount": reviews.length,
        "bestRating": "5",
        "worstRating": "1"
      },
      "review": reviews.slice(0, 20).map(r => ({
        "@type": "Review",
        "author": { "@type": "Person", "name": r.nombre || "Cliente" },
        "reviewRating": { "@type": "Rating", "ratingValue": String(nota(r)), "bestRating": "5", "worstRating": "1" },
        "reviewBody": r.texto || ""
      }))
    };
    if (!el) {
      el = document.createElement('script');
      el.type = 'application/ld+json';
      el.id = 'reviewSchemaLd';
      document.head.appendChild(el);
    }
    el.textContent = JSON.stringify(schema);
  }

