  // Extraer ejercicios del plan actual
  function extractEjercicios() {
    const content = document.getElementById('todayContent')?.innerHTML || '';
    const ejerciciosEncontrados = [];

    // Buscar en el contenido HTML los ejercicios conocidos
    const keywords = Object.keys(variantesDB);
    keywords.forEach(key => {
      if (content.toLowerCase().includes(key.toLowerCase())) {
        ejerciciosEncontrados.push(key);
      }
    });

    // Si no encuentra específicos, añadir genéricos según deporte
    if (ejerciciosEncontrados.length === 0) {
      const deporte = userData.deporte || '';
      if (deporte.includes('Gimnasio') || deporte.includes('Fuerza')) {
        ejerciciosEncontrados.push('press banca', 'remo', 'sentadilla', 'plancha');
      } else if (deporte.includes('Running')) {
        ejerciciosEncontrados.push('rodaje', 'series');
      } else if (deporte.includes('Hyrox') || deporte.includes('CrossFit')) {
        ejerciciosEncontrados.push('sentadilla', 'peso muerto', 'wall balls', 'burpees');
      } else {
        ejerciciosEncontrados.push('sentadilla', 'press banca', 'plancha');
      }
    }

    return ejerciciosEncontrados;
  }

  function toggleFeedback() {
    const panel = document.getElementById('feedbackPanel');
    const isVisible = panel.style.display !== 'none';

    if (isVisible) {
      panel.style.display = 'none';
      return;
    }

    // Resetear estado
    selectedEjercicios = [];
    selectedVariants = {};
    document.getElementById('feedbackStep1').style.display = 'block';
    document.getElementById('feedbackStep2').style.display = 'none';
    document.getElementById('feedbackStep3').style.display = 'none';

    // Limpiar selecciones de sensación
    document.querySelectorAll('#feedbackStep1 .radio-opt').forEach(o => o.classList.remove('selected'));

    // Generar lista de ejercicios
    const ejercicios = extractEjercicios();
    const lista = document.getElementById('ejerciciosList');
    lista.innerHTML = '';

    ejercicios.forEach(key => {
      const data = variantesDB[key];
      if (!data) return;
      const nVariantes = data.variantes ? data.variantes.length : 0;
      lista.innerHTML += `
        <div class="ejercicio-check" onclick="toggleEjercicio(this,'${key}')"
          style="display:flex;align-items:center;gap:14px;padding:16px 18px;background:var(--grafito);border:1px solid var(--humo);cursor:pointer;transition:all 0.2s;border-radius:4px">
          <div class="ej-box" style="width:24px;height:24px;border:2px solid var(--humo);border-radius:4px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:13px;transition:all 0.2s"></div>
          <div style="flex:1">
            <div style="font-size:14px;font-weight:600;color:var(--blanco)">${data.nombre}</div>
          </div>
          <div style="font-size:10px;color:var(--metal);background:var(--acero);padding:4px 8px;border-radius:3px;white-space:nowrap">${nVariantes} alternativas</div>
        </div>`;
    });

    panel.style.display = 'block';
    panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function toggleEjercicio(el, key) {
    const idx = selectedEjercicios.indexOf(key);
    const box = el.querySelector('.ej-box');
    if (idx === -1) {
      selectedEjercicios.push(key);
      el.style.borderColor = 'var(--brasa)';
      el.style.background = 'rgba(209,66,14,0.08)';
      box.textContent = '✓';
      box.style.background = 'var(--brasa)';
      box.style.borderColor = 'var(--brasa)';
      box.style.color = 'white';
    } else {
      selectedEjercicios.splice(idx, 1);
      el.style.borderColor = 'var(--humo)';
      el.style.background = 'var(--acero)';
      box.textContent = '';
      box.style.background = 'transparent';
      box.style.borderColor = 'var(--humo)';
    }
  }

  function selectFeedback(el, group) {
    document.querySelectorAll(`[onclick*="selectFeedback"][onclick*="${group}"]`).forEach(o => o.classList.remove('selected'));
    el.classList.add('selected');
  }

  function showVariants() {
    if (selectedEjercicios.length === 0) {
      showToast('Selecciona al menos un ejercicio para ver variantes');
      return;
    }

    document.getElementById('feedbackStep1').style.display = 'none';
    document.getElementById('feedbackStep2').style.display = 'block';

    const container = document.getElementById('variantsContent');
    container.innerHTML = `<p style="font-size:14px;color:var(--metal);margin-bottom:28px;font-weight:300">Elige la variante que prefieras para cada ejercicio. El plan se actualizará con tu selección.</p>`;

    selectedEjercicios.forEach(key => {
      const data = variantesDB[key];
      if (!data) return;

      container.innerHTML += `
        <div style="margin-bottom:32px">
          <div style="font-family:'Bebas Neue',sans-serif;font-size:22px;letter-spacing:1px;margin-bottom:4px;color:var(--blanco)">
            Cambiar: ${data.nombre}
          </div>
          <div style="font-size:11px;color: var(--brasa-txt);font-family:'DM Mono',monospace;letter-spacing:2px;text-transform:uppercase;margin-bottom:16px">
            // Elige una variante
          </div>
          <div style="display:flex;flex-direction:column;gap:8px" id="variants-${key}">
            ${data.variantes.map((v, i) => `
              <div onclick="selectVariant(this,'${key}',${i})"
                style="padding:18px 20px;background:var(--carbon);border:1px solid var(--humo);cursor:pointer;transition:all 0.2s"
                class="variant-opt">
                <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:16px">
                  <div>
                    <div style="font-size:14px;font-weight:600;margin-bottom:6px">${v.nombre}</div>
                    <div style="font-size:12px;color:var(--metal);line-height:1.5">${v.desc}</div>
                  </div>
                  <div style="font-size:10px;letter-spacing:1px;text-transform:uppercase;font-family:'DM Mono',monospace;color:var(--metal);white-space:nowrap;margin-top:2px;padding:4px 10px;background:var(--grafito)">${v.nivel}</div>
                </div>
              </div>`).join('')}
          </div>
        </div>`;
    });
  }

  function selectVariant(el, key, idx) {
    document.querySelectorAll(`#variants-${key} .variant-opt`).forEach(o => {
      o.style.borderColor = 'var(--humo)';
      o.style.background = 'var(--carbon)';
    });
    el.style.borderColor = 'var(--brasa)';
    el.style.background = 'rgba(209,66,14,0.08)';
    selectedVariants[key] = idx;
  }

  function skipFeedbackExercises() {
    const sensacion = document.querySelector('#feedbackStep1 .radio-opt.selected')?.textContent?.trim() || '';
    let mensaje = '';
    if (sensacion.includes('tope')) {
      mensaje = 'Perfecto, se nota que vas con todo. Tu plan sigue igual — si funciona, no hay que tocarlo. ¡A por el entreno!';
    } else if (sensacion.includes('Cansado')) {
      mensaje = 'Semana dura pero sigues aquí, eso es lo que cuenta. Tu plan no cambia — descansa bien hoy y mañana con más fuerza.';
    } else if (sensacion.includes('molestia')) {
      mensaje = 'Si la molestia es leve y no te impide entrenar, adelante con cuidado. Si persiste, vuelve y cambia el ejercicio que te moleste.';
    } else {
      mensaje = 'Todo correcto, tu plan sigue como estaba. A por el entreno de hoy.';
    }
    document.getElementById('feedbackStep1').style.display = 'none';
    document.getElementById('feedbackStep3').style.display = 'block';
    document.getElementById('feedbackConfirmMsg').textContent = mensaje;
    showToast('Todo bien, a entrenar.');
  }

  function confirmVariants() {
    if (Object.keys(selectedVariants).length === 0) {
      showToast('Selecciona al menos una variante para confirmar');
      return;
    }

    // Construir mensaje de confirmación
    const cambios = Object.entries(selectedVariants).map(([key, idx]) => {
      const data = variantesDB[key];
      const variante = data.variantes[idx];
      return `${data.nombre} → ${variante.nombre}`;
    });

    const sensacion = document.querySelector('#feedbackStep1 .radio-opt.selected')?.textContent?.trim() || '';

    let mensaje = '';
    if (sensacion.includes('tope')) {
      mensaje = 'Bien. Con esa energía los cambios son por preferencia, no por necesidad. ';
    } else if (sensacion.includes('Cansado')) {
      mensaje = 'Semana dura, lo entendemos. Los cambios que has elegido son más conservadores. Hoy apareces, eso es lo que importa. ';
    } else if (sensacion.includes('molestia')) {
      mensaje = 'Si hay molestia, la variante es lo correcto. No fuerces lo que el cuerpo no pide. ';
    } else {
      mensaje = 'Cambios registrados. ';
    }

    mensaje += `Tu entreno de hoy queda actualizado con: ${cambios.join(', ')}. El plan de la semana que viene también lo tendrá en cuenta.`;

    document.getElementById('feedbackStep2').style.display = 'none';
    document.getElementById('feedbackStep3').style.display = 'block';
    document.getElementById('feedbackConfirmMsg').textContent = mensaje;

    // Guardar preferencias del usuario y aplicarlas YA al plan real (no solo mostrar texto)
    userData.variantPreferences = userData.variantPreferences || [];
    userData.variantPreferences.push({ fecha: new Date().toISOString(), cambios: selectedVariants });

    generatedPlan = buildPlanFromData(userData);
    buildDashboard();

    const user = getCurrentUser();
    if (user) {
      saveUserData(user.email, { userData, plan: generatedPlan, savedAt: new Date().toISOString() });
    }

    showToast('Entreno actualizado. ¡A por ello!');
  }

  // ===== BANNER DE COOKIES =====
  // "kone_cookies_ok": '1' = aceptó analítica, '0' = solo necesarias. Antes
  // solo existía "Entendido" y ni siquiera hacía falta pulsarlo para que GA
  // ya estuviera corriendo — ahora GA solo arranca aquí, tras un consentimiento
  // real, o en la carga de página si ya se había aceptado antes (ver <head>).
  function aceptarCookies() {
    try { localStorage.setItem('kone_cookies_ok', '1'); } catch(e) {}
    cargarGA();
    try { cargarMeta(); } catch(e) {}
    const b = document.getElementById('cookieBanner');
    if (b) b.style.display = 'none';
  }
  function rechazarCookies() {
    try { localStorage.setItem('kone_cookies_ok', '0'); } catch(e) {}
    const b = document.getElementById('cookieBanner');
    if (b) b.style.display = 'none';
  }
  function mostrarCookieBanner() {
    try { if (localStorage.getItem('kone_cookies_ok') !== null) return; } catch(e) {}
    const b = document.getElementById('cookieBanner');
    if (b) { b.style.display = ''; b.classList.add('visible'); }
  }

  // ===== TEMA: forzado oscuro (decisión de diseño, ver dirección visual) =====
  // Hubo un selector claro/oscuro completo (toggleTheme/actualizarBotonTema);
  // se retiró porque no había ningún botón que lo llamara ni los elementos
  // #themeIcon/#themeLabel que actualizaba -- quedaba como código muerto sin
  // ningún efecto real. El CSS [data-theme="light"] (144 reglas, ~16 KB, que
  // nunca se aplicaban) se quitó el 1 oct 2026; está en el historial de git por
  // si se retoma el modo claro. Lo que sí se limpia aquí es el localStorage de
  // quien lo activó antes de esta decisión.
  (function() {
    // Modo claro desactivado — forzar oscuro siempre
    document.documentElement.removeAttribute('data-theme');
    try { localStorage.removeItem('kone_theme'); } catch(e) {}
  })();

  // ===== DETECTOR OFFLINE =====
  window.addEventListener('offline', () => {
    showToast('Sin conexión a internet. Algunas funciones no estarán disponibles.', 5000);
  });
  window.addEventListener('online', () => {
    showToast('Conexión restaurada.', 3000);
  });

  // ===== JWT AUTO-REFRESH =====
  setInterval(async () => {
    try {
      const { data } = await supa.auth.getSession();
      if (data?.session) await supa.auth.refreshSession();
    } catch(e) { console.warn('[auth] Error refrescando sesión:', e.message); }
  }, 45 * 60 * 1000);

  // ===== INIT =====
  window.onerror = function(mensaje, fuente) {
    // Errores de código ajeno (el puente del WebView de Instagram/Facebook, una
    // extensión...) no son un fallo de la app: no se le pone un cartel al cliente.
    if (/postMessage|Java object is gone|JavaBridge|webkit\.messageHandlers|__gCrWeb/i.test(String(mensaje || ''))
        || (fuente && String(fuente).indexOf(location.host) === -1)) return;
    var hasVisible = document.querySelector('.screen.active') ||
                     document.querySelector('.screen[style*="display: block"], .screen[style*="display:block"]');
    if (!hasVisible) {
      var landing = document.getElementById('landing');
      if (landing) { landing.classList.add('active'); landing.style.display = 'block'; }
      // Antes esto dejaba al usuario de vuelta en la landing sin explicar
      // nada -- si venía de mitad del cuestionario o del dashboard, no
      // tenía forma de saber que algo había fallado. showToast puede no
      // existir todavía si el error ocurrió durante el parseo inicial del
      // script, de ahí el try/catch (para no generar un segundo error
      // dentro del propio manejador de errores).
      try {
        if (typeof showToast === 'function') {
          showToast('Algo ha ido mal. Si estabas a mitad de algo, inténtalo de nuevo — si persiste, escríbenos.', 6000);
        }
      } catch (e) {}
    }
  };

  // ===== ACCESIBILIDAD: operabilidad por teclado de los pseudo-botones =====
  // Auditoría de accesibilidad (29 ago 2026): todo el cuestionario de alta
  // (radio-opt/check-opt), la navegación "volver"/logo de las pantallas de
  // login/registro, y en general cualquier elemento con onclick que no sea
  // ya un <button>/<a> nativo, no tenían tabindex ni respondían a
  // Enter/Espacio -- inoperables para quien navega solo con teclado. El
  // patrón correcto ya existía en un solo sitio (enlaces del menú, con
  // tabindex/role/onkeydown a mano) pero no se había replicado en el resto.
  // Como mucho de ese contenido se genera dinámicamente (innerHTML) después
  // de cargar la página -- el cuestionario, el dashboard, los modales -- un
  // MutationObserver reetiqueta cualquier [onclick] nuevo, en vez de tocar
  // las más de 400 líneas que ya usan onclick.
  function _marcarOperablesTeclado(raiz) {
    (raiz || document).querySelectorAll('[onclick]:not([tabindex])').forEach(el => {
      if (['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(el.tagName)) return;
      el.setAttribute('tabindex', '0');
      if (!el.hasAttribute('role')) el.setAttribute('role', 'button');
    });
    // Auditoría de accesibilidad (2 sept 2026): las opciones tipo radio
    // (enfermedad, alergia, valoración por estrellas, tipo de plan...) ya
    // eran operables por teclado gracias al bloque de arriba, pero con
    // role="button" -- un lector de pantalla las anunciaba como botones
    // sueltos, sin decir que forman parte de un grupo de elección única ni
    // cuál está marcada. selectRadio() mantiene aria-checked al día cuando
    // cambia la selección; esto solo pone el rol/estado inicial.
    (raiz || document).querySelectorAll('.radio-opt').forEach(el => {
      el.setAttribute('role', 'radio');
      el.setAttribute('aria-checked', el.classList.contains('selected') ? 'true' : 'false');
      const grupo = el.parentElement;
      if (grupo && !grupo.hasAttribute('role')) grupo.setAttribute('role', 'radiogroup');
    });
    // Mismo motivo que .radio-opt de arriba, para el grupo de botones del
    // check-in semanal (días entrenados, cómo fue físicamente...) --
    // selectRating() mantiene esto al día cuando cambia la selección.
    (raiz || document).querySelectorAll('.rating-btn:not([aria-pressed])').forEach(el => {
      el.setAttribute('aria-pressed', el.classList.contains('selected') ? 'true' : 'false');
    });
  }
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const el = e.target.closest('[onclick][tabindex]');
    if (!el || ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(el.tagName)) return;
    e.preventDefault();
    el.click();
  });
  // Sustituye cada <select class="jv-select"> por un botón + lista propia
  // con nuestro estilo de cristal: el listado nativo de un <select> es una
  // ventana del sistema operativo, y en Windows Chrome no la repinta con
  // color-scheme (a diferencia de macOS) -- seguía saliendo blanca pasara lo
  // que pasara con el CSS del control cerrado. El <select> original queda
  // oculto (display:none) como única fuente de verdad de su valor: todo el
  // código que ya hacía document.getElementById(id).value o escuchaba
  // "change" sigue funcionando sin tocar nada más.
  // Auditoría de accesibilidad (2 sept 2026): la primera versión de esto
  // ocultaba el <select> con display:none -- eso lo saca por completo del
  // árbol de accesibilidad, así que para alguien con lector de pantalla o
  // que navega solo con teclado dejó de existir un desplegable operable: el
  // botón no decía que abría una lista, la lista no tenía ningún rol y no
  // había forma de moverse por las opciones salvo con el ratón. Reescrito
  // como un combobox ARIA real: aria-haspopup/aria-expanded en el botón,
  // role="listbox"/"option"+aria-selected en la lista, flechas arriba/abajo
  // + Home/End + Enter/Escape, y foco visible.
  let _jvSelectSeq = 0;
  function _mejorarSelects(raiz) {
    (raiz || document).querySelectorAll('select.jv-select:not([data-mejorado])').forEach(sel => {
      sel.setAttribute('data-mejorado', '1');
      const idBase = 'jv-select-' + (++_jvSelectSeq);
      const wrap = document.createElement('span');
      wrap.className = 'jv-select-wrap';
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'jv-select-btn';
      btn.id = idBase + '-btn';
      btn.setAttribute('role', 'combobox');
      btn.setAttribute('aria-haspopup', 'listbox');
      btn.setAttribute('aria-expanded', 'false');
      const list = document.createElement('div');
      list.className = 'jv-select-list';
      list.id = idBase + '-list';
      list.setAttribute('role', 'listbox');
      list.tabIndex = -1;
      list.style.display = 'none';
      btn.setAttribute('aria-controls', list.id);
      const chevron = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';

      let opts = [];
      const pintarBoton = () => {
        const opt = sel.options[sel.selectedIndex];
        btn.innerHTML = '<span>' + (opt ? _esc(opt.textContent) : '') + '</span>' + chevron;
      };
      const cerrar = (devolverFoco) => {
        list.style.display = 'none';
        wrap.classList.remove('jv-select-wrap-open');
        btn.setAttribute('aria-expanded', 'false');
        btn.removeAttribute('aria-activedescendant');
        if (devolverFoco) btn.focus();
      };
      const enfocarOpcion = (idx) => {
        opts.forEach(o => o.tabIndex = -1);
        const el = opts[idx];
        if (!el) return;
        el.tabIndex = 0;
        el.focus();
        btn.setAttribute('aria-activedescendant', el.id);
      };
      const abrir = () => {
        document.querySelectorAll('.jv-select-wrap-open').forEach(w => {
          if (w === wrap) return;
          w.classList.remove('jv-select-wrap-open');
          const l = w.querySelector('.jv-select-list'); if (l) l.style.display = 'none';
          const b = w.querySelector('.jv-select-btn'); if (b) b.setAttribute('aria-expanded', 'false');
        });
        list.innerHTML = [...sel.options].map((o, i) =>
          '<div class="jv-select-opt' + (i === sel.selectedIndex ? ' jv-select-opt-active' : '') + '" id="' + idBase + '-opt-' + i + '" role="option" aria-selected="' + (i === sel.selectedIndex) + '" tabindex="-1" data-i="' + i + '">' + _esc(o.textContent) + '</div>'
        ).join('');
        opts = [...list.querySelectorAll('.jv-select-opt')];
        list.style.display = 'block';
        wrap.classList.add('jv-select-wrap-open');
        btn.setAttribute('aria-expanded', 'true');
        enfocarOpcion(sel.selectedIndex >= 0 ? sel.selectedIndex : 0);
      };
      const elegir = (idx) => {
        sel.selectedIndex = idx;
        sel.dispatchEvent(new Event('change', { bubbles: true }));
        pintarBoton();
        cerrar(true);
      };

      pintarBoton();
      sel._jvSync = pintarBoton;
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (list.style.display === 'none') abrir(); else cerrar(false);
      });
      btn.addEventListener('keydown', (e) => {
        if (['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(e.key) && list.style.display === 'none') {
          e.preventDefault();
          abrir();
        }
      });
      list.addEventListener('click', (e) => {
        const opt = e.target.closest('.jv-select-opt');
        if (opt) elegir(Number(opt.dataset.i));
      });
      list.addEventListener('keydown', (e) => {
        const actual = opts.indexOf(document.activeElement);
        if (e.key === 'ArrowDown') { e.preventDefault(); enfocarOpcion(Math.min(opts.length - 1, actual < 0 ? 0 : actual + 1)); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); enfocarOpcion(Math.max(0, actual < 0 ? 0 : actual - 1)); }
        else if (e.key === 'Home') { e.preventDefault(); enfocarOpcion(0); }
        else if (e.key === 'End') { e.preventDefault(); enfocarOpcion(opts.length - 1); }
        else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); if (actual >= 0) elegir(actual); }
        else if (e.key === 'Escape') { e.preventDefault(); cerrar(true); }
        else if (e.key === 'Tab') { cerrar(false); }
      });

      sel.style.display = 'none';
      sel.setAttribute('aria-hidden', 'true');
      sel.tabIndex = -1;
      sel.parentNode.insertBefore(wrap, sel);
      wrap.appendChild(sel);
      wrap.appendChild(btn);
      wrap.appendChild(list);
    });
  }
  document.addEventListener('click', () => {
    document.querySelectorAll('.jv-select-wrap-open').forEach(w => {
      w.classList.remove('jv-select-wrap-open');
      const l = w.querySelector('.jv-select-list'); if (l) l.style.display = 'none';
      const b = w.querySelector('.jv-select-btn'); if (b) b.setAttribute('aria-expanded', 'false');
    });
  });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') document.querySelectorAll('.jv-select-list').forEach(l => l.style.display = 'none'); });

  _marcarOperablesTeclado();
  _mejorarSelects();
  new MutationObserver((mutaciones) => {
    for (const m of mutaciones) {
      if (m.addedNodes.length) { _marcarOperablesTeclado(); _mejorarSelects(); break; }
    }
  }).observe(document.body, { childList: true, subtree: true });

  // Modales como diálogo real: role/aria-modal (son contenedores estáticos ya
  // presentes en el HTML inicial, solo cambian de visibilidad) + Escape para
  // cerrar el que esté abierto. Reutiliza el mismo patrón "click en el fondo
  // cierra" que ya usan la mayoría de modales (onclick="if(event.target===
  // this)cerrarX()"): un click sintético SOBRE el propio overlay hace que
  // event.target sea ese overlay, así que ese onclick se dispara igual que
  // si el usuario hubiera clicado fuera -- sin tener que enumerar y llamar
  // a cada función cerrarX() por separado.
  document.querySelectorAll('.modal-overlay, .onboarding-modal, #modalJarvisCliente').forEach(el => {
    el.setAttribute('role', 'dialog');
    el.setAttribute('aria-modal', 'true');
  });
  const _SELECTOR_MODALES_ABIERTOS = '.modal-overlay.visible, .onboarding-modal.visible, #modalJarvisCliente.visible';
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const abiertos = [...document.querySelectorAll(_SELECTOR_MODALES_ABIERTOS)];
    if (!abiertos.length) return;
    const ultimo = abiertos[abiertos.length - 1];
    // Prioriza el botón "✕" real del modal (el mismo que ya usa cada uno para
    // cerrarse, con su propia función -- guardar cambios, limpiar estado,
    // etc.) sobre el truco de "clic en el fondo", que solo cierra los
    // modales que tienen el patrón onclick="if(event.target===this)...".
    const boton = ultimo.querySelector('.modal-close:not([style*="display:none"]):not([style*="display: none"])');
    if (boton) boton.click();
    else ultimo.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
  });

  // Auditoría de accesibilidad (2 sept 2026): aria-modal="true" es solo una
  // pista semántica -- no bloquea el Tab real. Sin esto, seguir pulsando Tab
  // dentro de un modal abierto (paywall, cuestionario, editar nota...) paseaba
  // el foco por elementos visualmente tapados detrás del overlay. Atrapa el
  // Tab dentro del ÚLTIMO modal abierto (mismo criterio que ya usa Escape) y
  // cicla entre sus elementos focuseables sin salir nunca de él.
  function _elementosFocuseables(contenedor) {
    return [...contenedor.querySelectorAll(
      'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
    )].filter(el => el.offsetParent !== null); // visible de verdad, no solo presente en el DOM
  }
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;
    const abiertos = [...document.querySelectorAll(_SELECTOR_MODALES_ABIERTOS)];
    if (!abiertos.length) return;
    const ultimo = abiertos[abiertos.length - 1];
    if (!ultimo.contains(document.activeElement)) return; // el foco ya se salió por otra vía, no forzarlo
    const focuseables = _elementosFocuseables(ultimo);
    if (!focuseables.length) return;
    const primero = focuseables[0], last = focuseables[focuseables.length - 1];
    if (e.shiftKey && document.activeElement === primero) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); primero.focus(); }
  });

  // Foco inicial al abrir un modal: sin esto, en móvil o pantallas ≤768px
  // (el único sitio que ya movía el foco -- buscador de alimento/ejercicio --
  // lo hacía solo si window.innerWidth > 768) el foco se quedaba donde
  // estuviera antes de abrir, fuera de la vista, y Tab paseaba por detrás del
  // overlay antes de llegar al modal.
  new MutationObserver((mutations) => {
    for (const m of mutations) {
      if (m.type !== 'attributes' || m.attributeName !== 'class') continue;
      const el = m.target;
      if (!el.matches?.('.modal-overlay, .onboarding-modal, #modalJarvisCliente')) continue;
      if (!el.classList.contains('visible')) continue;
      // Ya tenía el foco dentro (p.ej. lo puso el propio código del modal) --
      // no pisarlo.
      if (el.contains(document.activeElement) && document.activeElement !== document.body) continue;
      const focuseables = _elementosFocuseables(el);
      if (focuseables.length) {
        focuseables[0].focus();
      } else {
        el.setAttribute('tabindex', '-1');
        el.focus();
      }
    }
  }).observe(document.body, { attributes: true, attributeFilter: ['class'], subtree: true });

  document.addEventListener('click', ev => {
    const b = ev.target.closest && ev.target.closest('button[onclick*="goTo(\'bienvenida\')"]');
    if (!b) return;
    const zona = b.closest('nav, header, footer, section, [id]');
    kEvento('cta_empezar', { zona: (zona && (zona.id || zona.tagName.toLowerCase())) || 'landing', texto: (b.textContent || '').trim().slice(0, 30) });
  });

  window.onload = async () => {
    if (new URLSearchParams(location.search).get('cuenta') === 'eliminada') {
      history.replaceState({}, '', location.pathname);
      setTimeout(() => showToast('Tu cuenta y tus datos se han eliminado. Gracias por haber estado en K-ONE.', 8000), 600);
    }
    // Se lee antes de nada: goTo() borra el hash legal al salir de esa pantalla.
    const _hashLegal = (location.hash || '').slice(1);
    _sincronizarPrecios();
    cargarTestimoniosLanding();
    mostrarCookieBanner();
    updateProgress();
    document.getElementById('login-pass')?.addEventListener('keydown', e => { if(e.key==='Enter') login(); });
    document.getElementById('reg-pass2')?.addEventListener('keydown', e => { if(e.key==='Enter') registrar(); });

    // Si el navegador no deja guardar datos (ver el primer <script>), la app
    // funciona con una memoria temporal: se le dice al cliente qué pasa y qué
    // hacer, en vez de que la sesión desaparezca sin explicación al volver.
    if (window.__almacenamientoEnMemoria) {
      const enApp = /Instagram|FBAN|FBAV|FB_IAB|musical_ly|TikTok|BytedanceWebview/i.test(navigator.userAgent || '');
      showToast(enApp
        ? 'Estás en el navegador de la app y no deja guardar tu sesión. Para no tener que volver a entrar, abre k-one.fit en Chrome o Safari.'
        : 'Tu navegador no deja guardar datos de esta web: si cierras la pestaña tendrás que volver a entrar. Puedes permitirlo en los ajustes de privacidad del navegador.', 9000);
    }

    // Si vuelve de un enlace de recuperación de contraseña, Supabase emite este
    // evento: abrimos el modal directamente en el paso de elegir nueva contraseña.
    supa.auth.onAuthStateChange((event) => {
      if (event === 'PASSWORD_RECOVERY') {
        document.getElementById('modalForgot').classList.add('visible');
        document.getElementById('forgotStep1').style.display = 'none';
        document.getElementById('forgotStep2').style.display = 'block';
      }
      if (event === 'SIGNED_IN' && window.location.hash.includes('access_token')) {
        showToast('Email confirmado. Bienvenido/a a K-ONE.', 4000);
        window.history.replaceState({}, '', window.location.pathname);
      }
    });

    // Reintenta los avisos al admin que no llegaron a salir (típicamente el
    // "nuevo registro", que se dispara en el momento más frágil: justo tras
    // signUp, antes de confirmar el email). Sin await: no debe retrasar el
    // arranque de la app.
    _reintentarNotificacionesPendientes();

    // Restaura la sesión activa de Supabase (si la hay) y sincroniza el perfil.
    let session = null;
    try {
      const { data } = await supa.auth.getSession();
      session = data?.session;
      if (session) {
        await syncProfileFromSupabase(session.user);
      } else {
        clearCurrentUser();
      }
    } catch (e) {
      console.error('Error restaurando sesión:', e);
      clearCurrentUser();
    }

    // Repara la suscripción push si el servidor perdió su fila (ver el
    // comentario largo en _resincronizarPushSubscription). Sin await: no debe
    // retrasar el arranque.
    //
    // Va AQUÍ, después de restaurar la sesión, y no antes como estaba: la
    // función lo primero que hace es pedir la sesión y, si no la encuentra, se
    // rinde en silencio sin reintentar nunca. Lanzada antes de este bloque
    // competía con la restauración -- si el token había caducado y Supabase
    // estaba renovándolo, se encontraba sin sesión y no reparaba nada. Y eso
    // ocurre justo en el peor caso posible: al volver tras varios días sin
    // abrir la app, que es exactamente cuando iOS ya ha rotado el endpoint y la
    // fila del servidor hace falta rehacerla. Resultado: no volvía a llegar un
    // aviso nunca más, con el interruptor puesto.
    if (session && typeof _resincronizarPushSubscription === 'function') {
      _resincronizarPushSubscription();
    }

    // Tarjeta del mes gratis: vuelta de Stripe (ok/cancelada) o enlace del email (anadir).
    const sesionParam = new URLSearchParams(window.location.search).get('sesion');
    if (sesionParam) {
      window.history.replaceState({}, '', window.location.pathname);
      setTimeout(() => {
        try {
          const g = JSON.parse(localStorage.getItem('kone_sesion_' + getFechaHoyISO()) || 'null');
          if (g && !g.fin && document.getElementById('dashboard')?.classList.contains('active')) sesAbrir();
        } catch (e) {}
      }, 1200);
    }
    const tarjetaParam = new URLSearchParams(window.location.search).get('tarjeta');
    if (tarjetaParam) {
      window.history.replaceState({}, '', window.location.pathname);
      if (tarjetaParam === 'ok') { _estadoTarjeta = true; kEvento('tarjeta_anadida'); setTimeout(() => showToast('Tarjeta añadida. Seguirás con tu plan sin cortes al terminar el mes gratis.', 6000), 800); }
      else if (tarjetaParam === 'cancelada') setTimeout(() => showToast('No se ha añadido la tarjeta. Puedes hacerlo cuando quieras desde «Gestionar suscripción».', 6000), 800);
      else if (tarjetaParam === 'anadir') {
        if (session) setTimeout(() => anadirTarjeta(null), 1200);
        else setTimeout(() => showToast('Entra en tu cuenta y pulsa «Añadir tarjeta» en «Gestionar suscripción».', 6000), 800);
      }
    }

    // Vuelta desde Stripe Checkout (ver api/create-checkout-session.js).
    const checkoutParam = new URLSearchParams(window.location.search).get('checkout');
    if (checkoutParam) {
      window.history.replaceState({}, '', window.location.pathname);
      if (checkoutParam === 'cancelado') {
        showToast('Pago cancelado. Puedes intentarlo de nuevo cuando quieras.', 4000);
      } else {
        if (typeof gtag === 'function') gtag('event', 'purchase', { currency: 'EUR' });
      }
    }

    const user = getCurrentUser();
    actualizarNavSesion();
    if (user) {
      try {
        const saved = getUserData(user.email);
        if (saved && saved.plan) {
          loadUserDashboard(user.email);
          goTo('dashboard');
        } else {
          await _entrarTrasAutenticar(session && session.user);
        }
      } catch (e) {
        console.error('Error cargando dashboard:', e);
        goTo('landing');
      }
    } else {
      const goParam = new URLSearchParams(window.location.search).get('go');
      if (goParam === 'registro') {
        window.history.replaceState({}, '', window.location.pathname);
        // Los enlaces de las páginas de deporte y de los emails llevan aquí:
        // ahora el alta empieza por el cuestionario, no por la cuenta.
        goTo('bienvenida');
      } else {
        // La portada ya se veía desde el primer instante: no se sube arriba a quien
        // ya estaba leyendo. Si pulsó algo mientras cargaba la app, se hace ahora.
        goTo('landing', { mantenerScroll: true });
        const pulsado = (window.__colaPortada || []).slice(-1)[0];
        window.__colaPortada = [];
        if (pulsado && typeof window[pulsado[0]] === 'function') {
          try { window[pulsado[0]].apply(null, pulsado[1]); } catch (e) { console.warn('[portada] botón pendiente:', e.message); }
        }
      }
    }

    // Enlaces directos a los textos legales (k-one.fit/#privacidad, etc.).
    if (['aviso-legal', 'privacidad', 'terminos', 'cookies'].includes(_hashLegal)) goToLegal(_hashLegal);

    // Vuelta desde Stripe con pago completado: el webhook puede tardar 1-5s en actualizar
    // subscriptions en Supabase. Reintentamos syncProfile cada 2s hasta confirmar acceso.
    if (checkoutParam === 'exito' && session) {
      showToast('¡Pago confirmado! Verificando tu suscripción...', 3000);
      let intentos = 0;
      const verificarSuscripcion = async () => {
        try {
          const { data: { session: freshSession } } = await supa.auth.getSession();
          const authUser = freshSession?.user || session.user;
          await syncProfileFromSupabase(authUser);
          const u = getCurrentUser();
          if (u && tieneAccesoActivo(u.email)) {
            const modal = document.getElementById('modalPaywall');
            if (modal) modal.classList.remove('visible');
            showToast('¡Suscripción activada! Bienvenido a K-One.', 4000);
            if (!userData.onboardingCompletado) startOnboarding();
          } else if (intentos < 9) {
            intentos++;
            setTimeout(verificarSuscripcion, 2000);
          } else {
            showToast('El pago se está procesando. Si en unos minutos no se activa, escríbenos.', 8000);
          }
        } catch (e) {
          console.warn('[verificarSuscripcion] Error de red:', e.message);
          if (intentos < 9) { intentos++; setTimeout(verificarSuscripcion, 3000); }
          else showToast('Error verificando suscripción. Recarga la página.', 8000);
        }
      };
      setTimeout(verificarSuscripcion, 1500);
    }

    // PWA Install Banner
    (function() {
      const isStandalone = window.navigator.standalone || window.matchMedia('(display-mode: standalone)').matches;
      if (isStandalone) return;
      if (localStorage.getItem('kone_pwa_dismissed')) return;
      const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent);
      const isAndroid = /android/i.test(navigator.userAgent);
      if (!isIOS && !isAndroid) return;

      let deferredPrompt = null;
      if (isAndroid) {
        window.addEventListener('beforeinstallprompt', function(e) {
          e.preventDefault();
          deferredPrompt = e;
        });
      }

      // Solo dentro del panel del cliente: antes salía a los 3 s a cualquier
      // visitante de móvil, encima de la portada, del registro o del
      // cuestionario, justo cuando aún no tiene nada que instalar.
      // ...y sin taparle el tour de bienvenida si lo está viendo.
      // ...ni encima de la guía de primera vez de cada sección (4 oct 2026: le
      // tapaba el botón «Entendido» a un cliente nuevo en el móvil) ni de un modal.
      const enPanel = () => document.getElementById('dashboard')?.classList.contains('active')
        && !(document.getElementById('onboardingModal') && getComputedStyle(document.getElementById('onboardingModal')).display !== 'none')
        && !document.getElementById('guiaSeccion')
        && !document.querySelector('.modal-overlay.visible')
        && !document.getElementById('sesionModo')?.classList.contains('abierta')
        // El primer día sobra: se ofrece cuando ya ha entrenado o lleva 2 días.
        && (((userData && userData.historialEntrenos) || []).length > 0
            || Date.now() - Date.parse((getCurrentUser() || {}).creado || 0) > 2 * 86400000);
      let esperas = 0;
      const cuandoEnPanel = fn => { if (enPanel()) setTimeout(fn, 3000); else if (++esperas < 120) setTimeout(() => cuandoEnPanel(fn), 5000); };
      cuandoEnPanel(function() {
        const banner = document.getElementById('pwaInstallBanner');
        const txt = document.getElementById('pwaInstallText');
        if (!banner || !txt || !enPanel()) return;
        if (isIOS) {
          txt.innerHTML = 'Usa K-ONE como una app. Toca <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#D1420E" stroke-width="2" style="vertical-align:-2px"><path d="M4 12v8a2 2 0 002 2h12a2 2 0 002-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg> <strong style="color:#fff">Compartir</strong> y luego <strong style="color:#fff">"Añadir a pantalla de inicio"</strong>.';
        } else {
          txt.innerHTML = 'Instala K-ONE como app para acceder más rápido desde tu pantalla de inicio.';
          if (deferredPrompt) {
            txt.innerHTML += ' <a onclick="window._pwaInstall()" style="color:#F26A36;cursor:pointer;font-weight:600;text-decoration:underline">Instalar ahora</a>';
          } else {
            txt.innerHTML += ' Toca <strong style="color:#fff">⋮</strong> y luego <strong style="color:#fff">"Instalar app"</strong>.';
          }
        }
        banner.style.display = '';
      });

      window._pwaInstall = function() {
        if (deferredPrompt) {
          deferredPrompt.prompt();
          deferredPrompt.userChoice.then(function() { deferredPrompt = null; });
          cerrarPwaBanner();
        }
      };
    })();

    window.cerrarPwaBanner = function() {
      const b = document.getElementById('pwaInstallBanner');
      if (b) b.style.display = 'none';
      localStorage.setItem('kone_pwa_dismissed', '1');
    };

    // ===== NOTIFICACIONES PUSH: recordatorio diario de entreno =====
    // Llamado desde buildDashboard() (después de cargarReferidos()) -- así se
    // sabe seguro que hay sesión (_supaUserId) y que el dashboard ya existe.
    // buildDashboard() se llama muchas veces por sesión (cada check-in,
    // regeneración de plan...) -- sin esta bandera, cada llamada arrancaba su
    // PROPIA cadena de reintentos independiente, y podían acabar varias
    // corriendo en paralelo si el banner de PWA se quedaba mucho tiempo visible.
    let _pushBannerChainActiva = false;
    window.mostrarBannerNotificaciones = function() {
      if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) return;
      if (Notification.permission !== 'default') return; // ya concedido o denegado antes
      if (localStorage.getItem('kone_push_dismissed')) return;
      if (!_supaUserId) return;
      if (_pushBannerChainActiva) return;
      _pushBannerChainActiva = true;
      const intentar = () => {
        // Revalidar en cada intento, no solo al programar el primero -- si
        // durante la espera el usuario ya activó/bloqueó los avisos desde el
        // interruptor, o cerró sesión, no tiene sentido enseñar el banner con
        // un estado que ya quedó obsoleto.
        if (Notification.permission !== 'default' || localStorage.getItem('kone_push_dismissed') || !_supaUserId) {
          _pushBannerChainActiva = false;
          return;
        }
        // No amontonar con el banner de instalar PWA, que ocupa el mismo hueco.
        const pwaBanner = document.getElementById('pwaInstallBanner');
        if (pwaBanner && pwaBanner.style.display !== 'none') { setTimeout(intentar, 6000); return; }
        // Ni en mitad de un entreno: taparía los botones de la sesión.
        if (document.getElementById('sesionModo')?.classList.contains('abierta')) { setTimeout(intentar, 15000); return; }
        const banner = document.getElementById('pushInstallBanner');
        // Solo nutrición: el aviso llega CADA día y habla de comidas (30 sept 2026).
        if (typeof generatedPlan !== 'undefined' && generatedPlan && generatedPlan.soloDieta) {
          const bt = document.getElementById('pushBannerTitulo'), bs = document.getElementById('pushBannerSub');
          if (bt) bt.textContent = 'Aviso diario de comidas';
          if (bs) bs.textContent = 'Cada día, tu menú listo. Se apaga cuando quieras.';
        }
        if (banner) banner.style.display = '';
        _pushBannerChainActiva = false;
      };
      setTimeout(intentar, 4000);
    };

    window.cerrarPushBanner = function() {
      const b = document.getElementById('pushInstallBanner');
      if (b) b.style.display = 'none';
      localStorage.setItem('kone_push_dismissed', '1');
    };

    function urlBase64ToUint8Array(base64String) {
      const padding = '='.repeat((4 - base64String.length % 4) % 4);
      const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
      const rawData = atob(base64);
      const outputArray = new Uint8Array(rawData.length);
      for (let i = 0; i < rawData.length; ++i) outputArray[i] = rawData.charCodeAt(i);
      return outputArray;
    }

    // Pide permiso, se suscribe al push del navegador y guarda la suscripción
    // en Supabase (insert directo protegido por RLS -- push_subscriptions_
    // insert_own -- sin gastar ninguna función serverless nueva). El envío
    // real lo hace el cron diario de api/notify.js con el service role.
    // Suscribe ESTE navegador a los avisos push y lo reclama en el servidor.
    // Un solo sitio para los dos pasos (antes solo vivían dentro de
    // activarNotificaciones) -- la reconciliación automática de más abajo
    // (_resincronizarPushSubscription) los necesita exactamente igual cuando
    // repara una suscripción que iOS revocó del todo, y con dos copias
    // sueltas era cuestión de tiempo que se desincronizaran.
    async function _suscribirPush() {
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
      });
      const json = sub.toJSON();
      // reclamar_push_subscription() (RPC, no insert directo): un mismo
      // endpoint push es único por NAVEGADOR, no por usuario -- en un
      // dispositivo compartido (tablet familiar, portátil de gimnasio), si
      // otro cliente ya había activado avisos antes en este mismo
      // navegador, un insert directo chocaba contra ese endpoint (23505) y
      // el error se descartaba en silencio: parecía que "ya estaba
      // suscrito", pero la fila seguía apuntando al OTRO cliente, que
      // seguía recibiendo el push en vez de ti. La función libera el
      // endpoint (lo borra, sea de quien sea) y lo vuelve a dar de alta a
      // tu nombre -- necesita permisos elevados que un insert normal
      // protegido por RLS no tiene.
      const { error } = await supa.rpc('reclamar_push_subscription', {
        p_endpoint: json.endpoint,
        p_p256dh: json.keys.p256dh,
        p_auth_key: json.keys.auth
      });
      if (error) throw error;
      return sub;
    }

    // "Los he apagado yo a propósito", recordado por usuario Y por dispositivo.
    // BUG REAL (27 sept 2026, reportado en el ordenador): al desactivar, la
    // suscripción del navegador se borra pero el PERMISO sigue concedido (no
    // se puede revocar por código). Al refrescar, _resincronizarPushSubscription
    // veía "permiso concedido + sin suscripción" -- la misma señal que deja iOS
    // cuando revoca la suscripción por su cuenta -- y la recreaba sin
    // preguntar: el interruptor volvía a aparecer encendido. Por dispositivo a
    // propósito: se pueden querer apagados en el ordenador y encendidos en el móvil.
    const _pushApagadoKey = uid => uid ? `kone_push_off_${uid}` : null;
    function _marcarPushApagado(uid, apagado) {
      try {
        const k = _pushApagadoKey(uid);
        if (!k) return;
        if (apagado) localStorage.setItem(k, '1'); else localStorage.removeItem(k);
      } catch (e) {}
    }
    function _pushApagadoPorUsuario(uid) {
      try { const k = _pushApagadoKey(uid); return !!(k && localStorage.getItem(k)); }
      catch (e) { return false; }
    }

    // Recordatorio diario de entreno: preferencia de la CUENTA, guardada en
    // userData (profiles.userdata), no en el navegador. BUG REAL (29 sept
    // 2026, reportado por el admin en ordenador y móvil: "apago los avisos de
    // entreno y al entrar vuelven a estar puestos"). "Avisos de entreno" y
    // "Avisos de registro" (Jarvis) eran el MISMO interruptor por dentro: los
    // dos solo miraban si el navegador tenía suscripción push. Apagar uno
    // apagaba el otro, encender los de registro volvía a encender los de
    // entreno, y el cron mandaba el recordatorio a cualquiera con suscripción.
    // Ahora la suscripción es "este dispositivo puede recibir avisos" y esta
    // preferencia decide si el cron manda el de entreno (api/notify.js la lee).
    function _avisosEntrenoActivos() {
      try { return !userData || userData.avisosEntreno !== false; } catch (e) { return true; }
    }
    function _guardarPrefAvisosEntreno(activos) {
      try {
        if (!userData || typeof userData !== 'object') return;
        if ((userData.avisosEntreno !== false) === activos) return;
        userData.avisosEntreno = activos;
        const user = getCurrentUser();
        if (user) saveUserData(user.email, { userData, plan: generatedPlan, savedAt: new Date().toISOString() });
      } catch (e) {
        console.warn('[push] no se pudo guardar la preferencia de avisos de entreno:', e.message);
      }
    }

    // tipo: 'entreno' (recordatorio diario, el del banner y el del menú del
    // cliente) o 'registro' (avisos de alta nueva, solo en Jarvis).
    window.activarNotificaciones = async function(tipo = 'entreno') {
      cerrarPushBanner();
      try {
        const permiso = await Notification.requestPermission();
        if (permiso !== 'granted') { showToast('No hemos podido activar los avisos.'); return; }
        await _suscribirPush();
        _marcarPushApagado(_supaUserId, false);
        if (tipo === 'entreno') _guardarPrefAvisosEntreno(true);
        showToast(tipo === 'registro'
          ? 'Avisos de registro activados en este dispositivo.'
          : ((typeof generatedPlan !== 'undefined' && generatedPlan && generatedPlan.soloDieta)
              ? 'Aviso diario activado. Cada día te recordaremos tus comidas.'
              : 'Avisos activados. Te avisaremos solo los días que no hayas entrenado.'));
      } catch (e) {
        console.warn('[push] Error activando notificaciones:', e.message);
        showToast('No se pudieron activar los avisos. Inténtalo de nuevo.', 4000);
      } finally {
        // finally, no al final del todo: el `return` de arriba cuando el
        // permiso se deniega salía de la función entera sin pasar por aquí
        // -- el interruptor se quedaba marcado y sin la pista de "bloqueado",
        // contradiciendo lo que de verdad pasó (bug real, encontrado
        // probando el flujo de denegar el permiso antes de este fix).
        await actualizarBotonNotificaciones();
      }
    };

    // Cancela la suscripción del navegador Y borra la fila en Supabase --
    // solo con lo primero, el navegador ya no llamaría a nuestro sw.js, pero
    // la fila se quedaría huérfana y el cron seguiría intentando mandarle
    // push a un endpoint que ya nadie escucha hasta que fallase con 404/410.
    window.desactivarNotificaciones = async function() {
      // Antes de cualquier await: aunque algo de abajo falle, la decisión del
      // usuario queda registrada y el próximo arranque no la deshace.
      _marcarPushApagado(_supaUserId, true);
      try {
        const reg = await navigator.serviceWorker.ready;
        const sub = await reg.pushManager.getSubscription();
        if (sub) {
          await supa.from('push_subscriptions').delete().eq('endpoint', sub.endpoint);
          await sub.unsubscribe();
        }
        showToast('Avisos desactivados.');
      } catch (e) {
        console.warn('[push] Error desactivando notificaciones:', e.message);
        showToast('No se pudieron desactivar los avisos. Inténtalo de nuevo.', 4000);
      } finally {
        // finally por el mismo motivo que en activarNotificaciones: que el
        // interruptor siempre acabe reflejando el estado real, pase lo que
        // pase dentro del try (hoy no hay ningún `return` temprano aquí,
        // pero así queda a prueba de que se añada uno en el futuro).
        await actualizarBotonNotificaciones();
      }
    };

    // Puede haber DOS interruptores en pantalla a la vez (barra del dashboard
    // de cliente + barra de Jarvis, si el admin tiene Jarvis abierto encima
    // de su propio dashboard) apuntando a la MISMA suscripción real del
    // navegador. Sin este candado, activar uno y desactivar el otro casi a
    // la vez podía intercalar subscribe()/insert con getSubscription()/
    // delete()/unsubscribe() y dejar el navegador suscrito sin fila en
    // Supabase (o una fila sin suscripción real) -- se deshabilitan TODOS
    // los interruptores mientras uno está en marcha, no solo el que se tocó.
    let _pushToggleBusy = false;
    window.onPushToggleChange = async function(checkbox) {
      if (_pushToggleBusy) {
        checkbox.checked = !checkbox.checked; // revierte el clic, no se procesa
        return;
      }
      _pushToggleBusy = true;
      document.querySelectorAll('[data-push-toggle] .push-toggle-input').forEach(i => { i.disabled = true; });
      // No se fuerza a "false" al terminar: actualizarBotonNotificaciones()
      // (llamada con await dentro de activar/desactivarNotificaciones) es la
      // única que decide el estado final de "disabled" -- si el navegador
      // acaba de bloquear el permiso, tiene que quedar deshabilitado con su
      // pista, no reactivarse a ciegas contradiciendo lo que el texto dice.
      const tipo = checkbox.dataset.pushTipo || 'entreno';
      try {
        if (tipo === 'registro') {
          // Sin suscripción en este dispositivo no llega nada, tampoco el de
          // entreno: su interruptor se pintará apagado, que es lo que pasa.
          if (checkbox.checked) await activarNotificaciones('registro');
          else await desactivarNotificaciones();
        } else if (checkbox.checked) {
          // Si el dispositivo ya estaba suscrito (el admin con los de registro
          // puestos) basta con la preferencia; si no, hay que suscribirlo.
          let yaSuscrito = false;
          try { yaSuscrito = !!(await (await navigator.serviceWorker.ready).pushManager.getSubscription()); } catch (e) {}
          if (yaSuscrito && Notification.permission === 'granted') {
            _guardarPrefAvisosEntreno(true);
            showToast((typeof generatedPlan !== 'undefined' && generatedPlan && generatedPlan.soloDieta) ? 'Aviso diario activado. Cada día te recordaremos tus comidas.' : 'Avisos activados. Te avisaremos solo los días que no hayas entrenado.');
            await actualizarBotonNotificaciones();
          } else {
            await activarNotificaciones('entreno');
          }
        } else {
          _guardarPrefAvisosEntreno(false);
          if (_adminVerificado) {
            // El admin conserva la suscripción para los avisos de registro.
            showToast((typeof generatedPlan !== 'undefined' && generatedPlan && generatedPlan.soloDieta) ? 'Aviso diario desactivado.' : 'Avisos de entreno desactivados.');
            await actualizarBotonNotificaciones();
          } else {
            await desactivarNotificaciones();
          }
        }
      } finally {
        _pushToggleBusy = false;
      }
    };

    // Decide qué mostrar en CADA interruptor de avisos que haya en la página
    // (el del dashboard de cliente y/o el de la barra lateral de Jarvis --
    // ambos leen la MISMA suscripción real del navegador, así que da igual
    // desde cuál se active/desactive, el otro se refleja solo la próxima vez
    // que se llame esto). Marcado si ya hay suscripción activa, desmarcado si
    // no, o deshabilitado con una pista si el propio usuario bloqueó el
    // permiso desde el navegador (Notification.permission === 'denied' no se
    // puede revertir por código, solo desde ahí -- mejor explicarlo que
    // esconder el interruptor sin más, que deja "¿y esto dónde se activa?"
    // sin respuesta).
    // RECONCILIACIÓN DE LA SUSCRIPCIÓN PUSH (bug real, 7 sept 2026).
    // El cron borra la fila de push_subscriptions en cuanto un envío falla con
    // 404/410 -- algo NORMAL en iOS: Apple caduca o rota el endpoint si el
    // móvil pasa un tiempo sin conexión. Pero el navegador conserva su
    // suscripción, así que getSubscription() sigue devolviéndola y el
    // interruptor de la app se queda marcado como ACTIVADO. Resultado: el
    // usuario cree que tiene los avisos puestos, el servidor ya no tiene a
    // quién mandárselos, y no vuelve a llegar ni un push -- sin ningún aviso
    // de que algo se ha roto. Encaja con los dos síntomas reportados: los
    // avisos de entreno "no llegan todos los días" y el push del alta nueva
    // no llegó nunca.
    // Con esto, cada vez que se abre la app se comprueba que la suscripción
    // del navegador SIGA dada de alta en el servidor y, si no, se vuelve a
    // reclamar con la misma RPC que usa el botón de activar.
    async function _resincronizarPushSubscription() {
      try {
        if (!('serviceWorker' in navigator) || !('PushManager' in window)) return;
        if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
        const { data: { session } } = await supa.auth.getSession();
        if (!session?.user) return;               // sin sesión no hay a quién asociarla
        // Apagados a propósito en este dispositivo: no se repara nada.
        if (_pushApagadoPorUsuario(session.user.id)) return;
        const reg = await navigator.serviceWorker.ready;
        const sub = await reg.pushManager.getSubscription();
        // Un cliente con los de entreno apagados en su cuenta no quiere ningún
        // aviso: aunque este navegador haya perdido la marca local (datos del
        // sitio borrados), no se le vuelve a suscribir por su cuenta.
        if (!sub && !_adminVerificado && !_avisosEntrenoActivos()) return;
        if (!sub) {
          // BUG REAL (12 sept 2026, reportado: avisos que dejan de llegar sin
          // avisar en iPhone con la app instalada). Hasta ahora, si iOS
          // revocaba la suscripción ENTERA del dispositivo (no solo perdía
          // la fila del servidor, que es lo que cubre el bloque de abajo),
          // getSubscription() devolvía null y aquí no se hacía nada -- el
          // interruptor se quedaba apagado en silencio hasta que alguien
          // entraba a mirar el menú a mano. Notification.permission sigue en
          // 'granted' aunque la suscripción haya muerto (son cosas
          // distintas): eso es justo la señal de que el usuario SÍ quiere
          // los avisos -- los aceptó una vez -- y hay que reponérselos, no
          // preguntarle otra vez. requestPermission() no muestra ningún
          // diálogo cuando el permiso ya está concedido, así que
          // _suscribirPush() se puede llamar aquí sin que el usuario toque nada.
          try {
            await _suscribirPush();
            console.log('[push] suscripción recreada (iOS había revocado la anterior)');
          } catch (e) {
            console.warn('[push] no se pudo recrear la suscripción revocada:', e.message);
          }
          return;
        }
        const json = sub.toJSON();
        const { data: filas, error } = await supa
          .from('push_subscriptions').select('id').eq('endpoint', json.endpoint).limit(1);
        if (error) return;                         // ante la duda, no tocar nada
        if (filas && filas.length) return;         // todo en orden
        // La fila ya no está: se vuelve a reclamar el endpoint para este usuario.
        const { error: errRpc } = await supa.rpc('reclamar_push_subscription', {
          p_endpoint: json.endpoint,
          p_p256dh: json.keys.p256dh,
          p_auth_key: json.keys.auth
        });
        if (errRpc) console.warn('[push] no se pudo re-registrar la suscripción:', errRpc.message);
        else console.log('[push] suscripción re-registrada (la fila del servidor se había perdido)');
      } catch (e) {
        console.warn('[push] resincronización fallida:', e.message);
      }
    }
    window._suscribirPush = _suscribirPush; // para comprobación externa, igual que la de abajo
    window._resincronizarPushSubscription = _resincronizarPushSubscription;

    // Manda un push a ESTE usuario ahora mismo. Hasta ahora la única forma de
    // saber si los avisos llegaban era esperar al cron diario, y si no llegaba
    // nada no había manera de saber en qué punto se rompía. Cada motivo que
    // devuelve el servidor se traduce a algo accionable, no a "error".
    window.probarNotificacion = async function(btn) {
      const textoOriginal = btn.textContent;
      btn.disabled = true; btn.textContent = 'Enviando...';
      try {
        const { data: { session } } = await supa.auth.getSession();
        if (!session) { showToast('Inicia sesión para probar los avisos.', 4000); return; }
        const r = await fetch('/api/notify', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session.access_token}` },
          body: JSON.stringify({ tipo: 'push_prueba', datos: {} })
        });
        const j = await r.json().catch(() => ({}));
        if (j.ok) {
          showToast(j.dispositivos > 1
            ? `Aviso enviado a tus ${j.dispositivos} dispositivos. Si no lo ves, revisa las notificaciones del sistema.`
            : 'Aviso enviado. Debería aparecerte en unos segundos.', 5000);
        } else if (j.motivo === 'sin_suscripcion') {
          showToast('Tus avisos no están registrados en el servidor. Apaga y vuelve a encender el interruptor.', 7000);
        } else if (j.motivo === 'sin_vapid') {
          showToast('Los avisos no están configurados en el servidor. Avísanos.', 7000);
        } else if (j.motivo === 'rechazado_por_el_navegador') {
          const caducada = (j.fallos || []).some(f => f.caducada);
          showToast(caducada
            ? 'Tu suscripción había caducado. Ya la hemos limpiado: apaga y vuelve a encender el interruptor.'
            : 'El navegador rechazó el aviso. Comprueba que K-ONE tenga permiso de notificaciones en los ajustes del móvil.', 8000);
        } else {
          showToast('No se pudo enviar el aviso de prueba.', 5000);
        }
        // El servidor puede haber borrado una suscripción caducada: que el
        // interruptor refleje el estado real y no siga diciendo "activado".
        await actualizarBotonNotificaciones();
      } catch (e) {
        console.warn('[push] prueba fallida:', e.message);
        showToast('No se pudo enviar el aviso de prueba.', 5000);
      } finally {
        btn.disabled = false; btn.textContent = textoOriginal;
      }
    };

    window.actualizarBotonNotificaciones = async function() {
      const contenedores = document.querySelectorAll('[data-push-toggle]');
      if (!contenedores.length) return;
      const soportado = ('serviceWorker' in navigator) && ('PushManager' in window) && ('Notification' in window);
      // iPhone/iPad: Safari solo expone PushManager si la web esta INSTALADA en la
      // pantalla de inicio (iOS 16.4+). En el navegador normal 'soportado' es
      // false, y hasta ahora eso escondia el bloque entero sin decir nada -- el
      // cliente de iPhone no veia los avisos por ninguna parte y no habia forma
      // de saber por que. Ahora se muestra con la instruccion concreta.
      const _esIOS = /iphone|ipad|ipod/i.test(navigator.userAgent)
        || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
      const _instalada = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
        || navigator.standalone === true;
      const _iosSinInstalar = !soportado && _esIOS && !_instalada;

      // Visibilidad ANTES de cualquier await. Si se espera a
      // serviceWorker.ready para decidir si se enseña, el interruptor tarda
      // hasta 4 segundos en aparecer y el cliente ve el menú sin él y luego
      // con él. Lo que decide si hay algo que ofrecer es sincrono; el await
      // de abajo solo sirve para saber si está encendido o apagado.
      // En un movil el interruptor NO se esconde nunca: si no se puede
      // activar, se enseña deshabilitado y con el motivo. Esconderlo deja al
      // cliente buscando una opcion que le hemos prometido y no encuentra,
      // que es exactamente lo que estaba pasando.
      const _esMovil = _esIOS || /android|mobile/i.test(navigator.userAgent);
      contenedores.forEach(cont => {
        cont.style.display = (soportado || _iosSinInstalar || _esMovil) ? '' : 'none';
        const inp = cont.querySelector('.push-toggle-input');
        // Deshabilitado mientras no se sabe el estado, pero solo la primera
        // vez: si ya se resolvió antes, dejarlo como está evita que parpadee
        // a "apagado" en cada llamada posterior.
        if (inp && !inp.dataset.estadoResuelto) inp.disabled = true;
      });

      let sub = null, denegado = false, hayError = false;
      if (soportado) {
        denegado = Notification.permission === 'denied';
        if (!denegado) {
          try {
            // `serviceWorker.ready` NO rechaza si no hay service worker activo:
            // se queda pendiente para siempre. Sin el límite de abajo, esta
            // función no llegaba nunca a la parte de pintar y el interruptor se
            // quedaba oculto (su estado inicial) sin decir por qué -- que es lo
            // que pasaba en el móvil aunque la app estuviera instalada.
            const reg = await Promise.race([
              navigator.serviceWorker.ready,
              new Promise((_, rej) => setTimeout(() => rej(new Error('service worker no listo')), 4000))
            ]);
            sub = await reg.pushManager.getSubscription();
          } catch (e) {
            console.warn('[push] no se pudo leer la suscripción:', e.message);
            hayError = true;
          }
        }
      }
      contenedores.forEach(cont => {
        const input = cont.querySelector('.push-toggle-input');
        const hint = cont.querySelector('.push-toggle-hint');
        // El botón de prueba se esconde de entrada y solo lo reactiva la rama
        // final, cuando consta que hay suscripción de verdad: no tiene sentido
        // ofrecer "mándame una prueba" a quien todavía no los ha activado.
        const btnPrueba = cont.querySelector('[data-push-test]');
        if (btnPrueba) btnPrueba.style.display = 'none';
        if (!input) return;
        if (_iosSinInstalar) {
          input.dataset.estadoResuelto = '1';
          cont.style.display = '';
          input.checked = false;
          input.disabled = true;
          if (hint) {
            hint.textContent = 'En iPhone los avisos solo funcionan con la app instalada: pulsa Compartir y luego «Añadir a pantalla de inicio». Después vuelve aquí y actívalos.';
            hint.style.display = '';
          }
          return;
        }
        // Si el navegador no soporta push se esconde SOLO en escritorio. En
        // movil se enseña deshabilitado con el motivo: un iPhone con la app
        // instalada pero con iOS anterior a 16.4 caia aqui (no es
        // _iosSinInstalar, porque SI esta instalada) y el bloque desaparecia
        // sin decir nada. El cliente no tenia forma de saber por que.
        if (!soportado) {
          if (!_esMovil) { cont.style.display = 'none'; return; }
          input.dataset.estadoResuelto = '1';
          cont.style.display = '';
          input.checked = false;
          input.disabled = true;
          if (hint) {
            hint.textContent = _esIOS
              ? 'Tu versión de iPhone no admite avisos web. Hacen falta iOS 16.4 o superior y la app añadida a la pantalla de inicio.'
              : 'Este navegador no admite avisos. Prueba a abrir K-ONE en Chrome.';
            hint.style.display = '';
          }
          return;
        }
        // Pero si SÍ lo soporta y solo es que el service worker aún no estaba
        // listo, esconderlo era lo peor: el cliente no veía el interruptor por
        // ninguna parte y no había forma de saber por qué. Se muestra
        // deshabilitado, con la pista, y se reintenta solo en cuanto el service
        // worker active (mismo criterio que el resto de estados de aquí).
        if (hayError) {
          cont.style.display = '';
          input.checked = false;
          input.disabled = true;
          if (hint) {
            hint.textContent = 'Preparando los avisos… si no se activa en unos segundos, cierra y vuelve a abrir la app.';
            hint.style.display = '';
          }
          if (!window._reintentoPushProgramado) {
            window._reintentoPushProgramado = true;
            navigator.serviceWorker.ready
              .then(() => { window._reintentoPushProgramado = false; actualizarBotonNotificaciones(); })
              .catch(() => { window._reintentoPushProgramado = false; });
          }
          return;
        }
        cont.style.display = '';
        input.dataset.estadoResuelto = '1';
        if (denegado) {
          input.checked = false;
          input.disabled = true;
          if (hint) {
            hint.textContent = 'Los bloqueaste desde el navegador. Actívalos desde los ajustes de notificaciones del sitio para volver a recibirlos aquí.';
            hint.style.display = '';
          }
          return;
        }
        input.disabled = false;
        // El de entreno necesita además la preferencia de la cuenta: el admin
        // puede tener el dispositivo suscrito solo por los de registro.
        const encendido = !!sub && (input.dataset.pushTipo !== 'entreno' || _avisosEntrenoActivos());
        input.checked = encendido;
        if (hint) {
          // Si no hay texto que enseñar (data-hint-on vacío o sin poner),
          // se esconde del todo -- si no, quedaba un hueco vacío con su
          // padding, como un renglón en blanco debajo del interruptor.
          const texto = encendido ? (input.dataset.hintOn || '') : '';
          hint.textContent = texto;
          hint.style.display = texto ? '' : 'none';
        }
        if (btnPrueba) btnPrueba.style.display = encendido ? '' : 'none';
      });
    };

    if ('serviceWorker' in navigator) {
      // BUG GORDO (encontrado 8 sept 2026): esto hacía unregister() de TODOS
      // los service workers y volvía a registrar EN CADA CARGA de la página.
      //
      // La suscripción push pertenece al registro del service worker: al
      // desregistrarlo, la PushSubscription del navegador muere con él. O sea
      // que cada vez que el cliente abría la app se destruía su suscripción y
      // se creaba un registro nuevo SIN suscripción. Consecuencias en cadena,
      // todas reportadas por el usuario estos dos días:
      //   · el interruptor de avisos aparecía apagado al volver a entrar
      //     (getSubscription() ya no devolvía nada),
      //   · la fila de push_subscriptions seguía apuntando al endpoint viejo,
      //     ya muerto -> el servidor recibía 410 y BORRABA la fila -> no
      //     volvía a llegar ni un push,
      //   · y si actualizarBotonNotificaciones() corría en la ventana entre el
      //     unregister y la activación del nuevo SW, `serviceWorker.ready` se
      //     quedaba colgado y el interruptor no llegaba a mostrarse siquiera.
      //
      // No hace falta desregistrar para actualizar: sw.js se sirve con
      // no-cache (ver vercel.json) y hace skipWaiting(), así que register()
      // solo ya recoge cualquier versión nueva.
      navigator.serviceWorker.register('/sw.js').catch(() => {});
      // No borrar caches aquí — el SW gestiona su propio ciclo de vida con versiones
    }

    // El interruptor de avisos se pinta también AQUÍ, no solo desde
    // buildDashboard(). Motivo (bug real, reportado el 11 sept 2026: "me sigue
    // desapareciendo lo de las notificaciones en el ordenador"):
    //
    // estas funciones se crean con `window.X = function`, que es una ASIGNACIÓN
    // y no una declaración, así que no se elevan: no existen hasta que la
    // ejecución llega a esta parte del onload. Pero la restauración de sesión
    // -- y con ella buildDashboard() -- está MÁS ARRIBA en este mismo onload, o
    // sea que cuando llama a actualizarBotonNotificaciones() todavía es
    // undefined y su `typeof === 'function'` la salta sin decir nada.
    //
    // En el móvil el fallo se tapaba solo: toggleDashMenu() vuelve a llamarla
    // cada vez que se abre el menú, y para entonces ya existe. En escritorio la
    // barra lateral está siempre abierta, no hay segunda llamada, y el
    // interruptor se quedaba oculto el resto de la sesión.
    if (session) {
      try { actualizarBotonNotificaciones(); } catch (e) {}
      try { mostrarBannerNotificaciones(); } catch (e) {}
    }
  };

